import { decodeProfile, encodeProfile } from "../codec/settingsCodec";
import { DeviceProfile } from "../domain/profile";
import { Revision, RevisionSource } from "../domain/revision";

interface Row {
  deviceId: string;
  rev: number;
  createdAt: number;
  source: RevisionSource;
  body: string;
  changed: string;
}

/** Append-only revision log, stored the way the database table holds it (encoded text). */
export class RevisionStore {
  private readonly rows: Row[] = [];
  private readonly latestIndex = new Map<string, number>();

  append(deviceId: string, profile: DeviceProfile, source: RevisionSource, createdAt: number, changed: string[]): Revision {
    const prev = this.latest(deviceId);
    const row: Row = {
      deviceId,
      rev: prev ? prev.rev + 1 : 1,
      createdAt,
      source,
      body: encodeProfile(profile),
      changed: changed.join(","),
    };
    this.rows.push(row);
    this.latestIndex.set(deviceId, this.rows.length - 1);
    return this.toRevision(row);
  }

  latest(deviceId: string): Revision | undefined {
    const i = this.latestIndex.get(deviceId);
    return i === undefined ? undefined : this.toRevision(this.rows[i]);
  }

  /** Newest first. */
  history(deviceId: string, limit: number): Revision[] {
    return this.rows
      .filter((r) => r.deviceId === deviceId)
      .sort((a, b) => b.rev - a.rev)
      .slice(0, limit)
      .map((r) => this.toRevision(r));
  }

  count(deviceId: string): number {
    return this.rows.filter((r) => r.deviceId === deviceId).length;
  }

  private toRevision(r: Row): Revision {
    return {
      deviceId: r.deviceId,
      rev: r.rev,
      createdAt: r.createdAt,
      source: r.source,
      profile: decodeProfile(r.body),
      changed: r.changed ? r.changed.split(",") : [],
    };
  }
}
import { SyncConfig } from "../config";
import { DesiredStore } from "../store/desiredStore";
import { RevisionStore } from "../store/revisionStore";
import { changedKeys } from "../util/diff";
import { needsUpgrade } from "../util/semver";

export interface SyncStatus {
  deviceId: string;
  state: "unknown" | "in-sync" | "drifted";
  reportedRev: number | null;
  drift: string[];
  firmwareMismatch: boolean;
  upgradeRecommended: boolean;
}

export class SyncStatusService {
  constructor(private readonly desired: DesiredStore, private readonly revisions: RevisionStore, private readonly config: SyncConfig) {}

  status(deviceId: string): SyncStatus {
    const want = this.desired.get(deviceId);
    const have = this.revisions.latest(deviceId);
    if (!want || !have) {
      return {
        deviceId,
        state: "unknown",
        reportedRev: have?.rev ?? null,
        drift: [],
        firmwareMismatch: false,
        upgradeRecommended: have ? needsUpgrade(have.profile.firmware, this.config.minimumFirmware) : false,
      };
    }
    const drift = changedKeys(want.settings, have.profile.settings, this.config.ignoredKeys);
    const firmwareMismatch = want.firmware !== have.profile.firmware;
    return {
      deviceId,
      state: drift.length === 0 && !firmwareMismatch ? "in-sync" : "drifted",
      reportedRev: have.rev,
      drift,
      firmwareMismatch,
      upgradeRecommended: needsUpgrade(have.profile.firmware, this.config.minimumFirmware),
    };
  }
}
export type SettingValue = number | string | boolean | null | SettingValue[] | { [key: string]: SettingValue };

export interface DeviceProfile {
  deviceId: string;
  name: string;
  firmware: string;
  settings: Record<string, SettingValue>;
}

export function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

export function validateProfile(p: unknown): string[] {
  const errors: string[] = [];
  if (!isPlainObject(p)) return ["profile must be an object"];
  if (typeof p.deviceId !== "string" || !p.deviceId) errors.push("deviceId is required");
  if (typeof p.name !== "string") errors.push("name must be a string");
  if (typeof p.firmware !== "string" || !/^\d+\.\d+\.\d+$/.test(p.firmware)) errors.push("firmware must look like 1.2.3");
  if (!isPlainObject(p.settings)) errors.push("settings must be an object");
  return errors;
}
import { DeviceProfile } from "../domain/profile";

/**
 * Storage encoding for profiles. Plain JSON cannot carry NaN or ±Infinity
 * (JSON.stringify turns them into null), so non-finite numbers are boxed.
 */
const BOX = "$num";

function box(_key: string, value: unknown): unknown {
  if (typeof value === "number" && !Number.isFinite(value)) {
    return { [BOX]: Number.isNaN(value) ? "NaN" : value > 0 ? "Infinity" : "-Infinity" };
  }
  return value;
}

function unbox(_key: string, value: unknown): unknown {
  if (typeof value === "object" && value !== null && !Array.isArray(value)) {
    const keys = Object.keys(value);
    if (keys.length === 1 && keys[0] === BOX) return Number((value as Record<string, string>)[BOX]);
  }
  return value;
}

export function encodeProfile(p: DeviceProfile): string {
  return JSON.stringify(p, box);
}

export function decodeProfile(text: string): DeviceProfile {
  return JSON.parse(text, unbox) as DeviceProfile;
}
import { SettingValue } from "../domain/profile";
import { valuesEqual } from "./deepEqual";

/** Top-level keys whose values differ (added, removed or changed), sorted. */
export function changedKeys(
  before: Record<string, SettingValue>,
  after: Record<string, SettingValue>,
  ignore: readonly string[] = [],
): string[] {
  const keys = new Set([...Object.keys(before), ...Object.keys(after)]);
  const out: string[] = [];
  for (const k of keys) {
    if (ignore.includes(k)) continue;
    const inBefore = Object.prototype.hasOwnProperty.call(before, k);
    const inAfter = Object.prototype.hasOwnProperty.call(after, k);
    if (inBefore !== inAfter || !valuesEqual(before[k], after[k])) out.push(k);
  }
  return out.sort();
}
